  "  date_add(DATE'2026-01-01', CAST(id % 30 AS INT)) AS event_date,",
  "  element_at(array('web','app','store'), CAST(id % 3 AS INT) + 1) AS channel,",
  "  CAST((id % 100) + 1 AS DECIMAL(12,2)) AS amount,",
